#!/usr/bin/env node
/**
 * Puts the hero and the landing PNGs into web/static/img for Docusaurus.
 *
 * - The hero is committed (assets/screenshots/code.png) and copied when
 *   web/static/img/code.png is missing.
 * - The landing PNGs are generated by e2e/desktop/landing (`npm run
 *   landing`), which writes them straight into web/static/img/landing/. In
 *   CI they arrive as the `landing-screenshots` artifact: pass its directory
 *   and the PNGs listed in src/data/landing-screenshots.json are copied in.
 *
 * Nothing is filled in for a missing PNG: assert-landing-screenshots.mjs
 * fails the build instead.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const webRoot = path.join(__dirname, "..");
const repoRoot = path.join(webRoot, "..");
const destImg = path.join(webRoot, "static", "img");
const destLanding = path.join(destImg, "landing");
const destHero = path.join(destImg, "code.png");
const committedHero = path.join(repoRoot, "assets", "screenshots", "code.png");
const listPath = path.join(webRoot, "src", "data", "landing-screenshots.json");
const names = JSON.parse(fs.readFileSync(listPath, "utf8"));
const srcRoot = process.argv[2];

function findNamed(dir, filename) {
  if (!fs.existsSync(dir)) return undefined;
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const next = path.join(dir, ent.name);
    if (ent.isDirectory()) {
      const found = findNamed(next, filename);
      if (found) return found;
    } else if (ent.name === filename) {
      return next;
    }
  }
  return undefined;
}

fs.mkdirSync(destLanding, { recursive: true });

if (srcRoot) {
  let copied = 0;
  for (const name of names) {
    const found = findNamed(srcRoot, name);
    if (!found) continue;
    fs.copyFileSync(found, path.join(destLanding, name));
    copied += 1;
  }
  console.log(
    `Copied ${copied} of ${names.length} landing PNG(s) from ${srcRoot}`,
  );
}

if (!fs.existsSync(destHero)) {
  fs.copyFileSync(committedHero, destHero);
  console.log(`Staged hero from ${committedHero}`);
}
